147	int stopDaemon(const std::filesystem::path& ws, int timeoutSeconds) {
148	    auto info = query(ws);
149	    if (info.state == DaemonState::NotRunning) return 0;
150	    // The lock file's pid is written by the holder under the flock —
151	    // prefer it over the separately-written (and possibly lagging) pidfile.
152	    if (int lockPid = readLockHolderPid(ws); lockPid > 0) info.pid = lockPid;
153	    if (info.pid <= 0) return 1;  // lock held but pid unknown: refuse to guess
154	    // Never signal a process we can't identify: if the pid doesn't look like
155	    // an nrvnad, someone else holds the lock (or the file is garbage) — refuse.
156	    if (!workspaceOwnedByNrvnad(ws, info.pid)) return 1;
157	
158	    (void)::kill(info.pid, SIGTERM);
159	    auto deadline = std::chrono::steady_clock::now() + std::chrono::seconds(timeoutSeconds);
160	    bool escalated = false;
161	    while (lockIsHeld(ws)) {
162	        if (std::chrono::steady_clock::now() >= deadline) {
163	            // Revalidate identity before every escalation signal. The flock
164	            // being held implies the holder is alive, but the pid we signal
165	            // must still be an nrvnad at the moment we signal it.
166	            if (!workspaceOwnedByNrvnad(ws, info.pid)) return 1;
167	            if (!escalated) {
168	                // nrvnad treats a second signal as "force exit now"
169	                (void)::kill(info.pid, SIGTERM);
170	                escalated = true;
171	                deadline += std::chrono::seconds(3);
172	            } else {
173	                (void)::kill(info.pid, SIGKILL);
174	                std::this_thread::sleep_for(std::chrono::seconds(1));
175	                break;
176	            }
177	        }
