# frozen 15: query | acceptable-target regex
run() {
  local q="$1" re="$2"
  local out; out=$(./build/imgsrch search "$P" "$q" --top-k 35 2>/dev/null)
  # min dense_rank and min bm25_rank across acceptable targets
  local dr br
  dr=$(printf '%s' "$out" | grep -E "images/($re)" | grep -oE 'dense_rank=[0-9]+' | grep -oE '[0-9]+' | sort -n | head -1)
  br=$(printf '%s' "$out" | grep -E "images/($re)" | grep -oE 'bm25_rank=[0-9]+' | grep -oE '[0-9]+' | sort -n | head -1)
  echo "$dr $br $q"
}
